/* Three, so a vsync Present rarely blocks the RSX thread (which also feeds
 * the SPU job pipeline its reports) waiting for a buffer to come free. */
#define LD_SWAP_BUFFERS  3
static int g_ld_vsync = 1, g_ld_tearing = 0;   /* PS3_VSYNC, set when the swap chain is made */
volatile long long g_ld_present_us;            /* time spent inside Present, for the [flush] line */
/* Frame pacing, for the [flush] line: the longest gap between two presents
 * and how many gaps exceeded 50 ms (a visible hitch) in the window. */
volatile long long g_ld_gap_max_us, g_ld_hitches;
/* Gap histogram: <20, 20-34, 34-50, 50-67, 67-100, >=100 ms. */
volatile long long g_ld_gap_hist[6];
/* LD_HITCH_MS (default 40; 0 off): a "[hitch]" line for every frame whose gap
 * between presents reaches it, saying what the present (RSX) thread did in
 * that frame: the walker's busy/idle split (cellGcmSys.c g_gcm_walk_cum_us),
 * pipeline builds and waits, texture decodes, GPU waits and the previous
 * Present. Sums kept per frame on that thread only (ld_hitch_clock is 0 on
 * any other thread). */
static struct {
    unsigned long long pso_us, pso_n, psowait_us, pso_skip, tex_us, tex_n;
    /* the texture misses in detail: content hash, CreateCommittedResource,
     * upload-ring wraps (a flush that waits for the GPU) and their count,
     * copies into the upload ring, bytes uploaded */
    unsigned long long tex_hash_us, tex_create_us, tex_ring_us, tex_ring_n, tex_copy_us, tex_bytes;
    unsigned long long hold_us;   /* LD_PSO_LOAD_HOLD: frames held before this present (not shown) */
} g_ld_ht;
static __declspec(thread) int t_ld_ht_thread;
static int g_ld_hitch_ms = -1;
static unsigned long long ld_hitch_clock(void)
{
    extern unsigned long long ps3_qpc_us(void);
    if (!t_ld_ht_thread || g_ld_hitch_ms <= 0) return 0;
    return ps3_qpc_us() | 1ull;
}
static void ld_hitch_frame(long long gap_us);   /* after the flush counters it reads */
volatile long long g_ld_present_main, g_ld_present_movie;
/* LD_TURBO_LOAD (default on; =0 off): a frame of 1-4 draws, a file read in
 * the last 3 s and no movie, for about a second (60 frames) in a row, is God
 * of War: Ascension's loading screen -- raise g_ps3_load_turbo (cellGcmSys.c)
 * so the game runs it at LD_TURBO_HZ; the first frame that is not drops it.
 * Called once per presented game frame. */
extern volatile int g_ps3_load_turbo;
extern volatile unsigned long long g_ps3_last_fs_read_us;
static void ld_pso_hold_load(int loading);   /* LD_PSO_LOAD_HOLD */
extern double ps3_load_turbo_hz(void);
extern volatile long long g_ld_draws_total;
static void ld_turbo_update(int movie)
{
    static int on = -1;
    if (on < 0) { const char* e = getenv("LD_TURBO_LOAD"); on = !(e && e[0] == '0'); }
    if (!on) return;
    extern unsigned long long ps3_qpc_us(void);
    static long long last_draws; static int frames;
    const long long d = g_ld_draws_total - last_draws;
    last_draws = g_ld_draws_total;
    const int reading = g_ps3_last_fs_read_us && ps3_qpc_us() - g_ps3_last_fs_read_us < 3000000ull;
    frames = (!movie && d >= 1 && d <= 4 && reading) ? (frames < 1000000 ? frames + 1 : frames) : 0;
    const int want = frames >= 60;
    if (want != g_ps3_load_turbo) {
        g_ps3_load_turbo = want;
        ld_pso_hold_load(want);   /* LD_PSO_LOAD_HOLD */
        static int n; if (n < 64 && ++n) {
            if (want) fprintf(stderr, "[turbo] loading screen: frames at %.0f Hz, no vsync\n", ps3_load_turbo_hz());
            else      fprintf(stderr, "[turbo] loading screen ended (%lld draws in the frame)\n", d);
        }
    }
}

/* [pacing] every 10 s (LD_PACING_LOG=0 off): how many monitor refreshes each
 * frame stayed on screen, from the swap chain's frame statistics, and the
 * refresh measured from them. A steady 60 FPS on a 60 Hz screen is all
 * "1"; on a 75 Hz screen it is three "1" for every "2" (a judder the FPS
 * counter does not show; PS3_DISPLAY_MATCH in rsx_host_window.h). Sampled
 * once per present, the statistics often move two or three frames at once;
 * with vsync no frame shows for less than one refresh, so k frames over k
 * refreshes are all "1", over k+1 one of them is "2"; anything else is
 * "unsampled". Reliable in full screen (the display's own statistics). */
static void ld_pacing_note(IDXGISwapChain3* sc, int vsync, unsigned long long now_us)
{
    static int on = -1, have;
    static UINT last_pc, last_prc, sync0;
    static LARGE_INTEGER qpc0;
    static unsigned long long win0;
    static u32 hist[4], unsampled, failed;   /* 1, 2, 3, 4+ refreshes */
    if (on < 0) { const char* e = getenv("LD_PACING_LOG"); on = !(e && e[0] == '0'); }
    if (!on) return;
    DXGI_FRAME_STATISTICS st;
    if (!vsync) { have = 0; return; }
    if (FAILED(sc->lpVtbl->GetFrameStatistics(sc, &st))) {
        have = 0;
        if (++failed == 600) printf("[pacing] no frame statistics from the swap chain\n");
        return;
    }
    if (have && st.PresentCount != last_pc) {
        const UINT dp = st.PresentCount - last_pc, dr = st.PresentRefreshCount - last_prc;
        if (dp == 1 && dr >= 1) hist[dr >= 4 ? 3 : dr - 1]++;
        else if (dp < 16 && dr == dp) hist[0] += dp;
        else if (dp < 16 && dr == dp + 1) { hist[0] += dp - 1; hist[1]++; }
        else unsampled += dp;
    }
    last_pc = st.PresentCount; last_prc = st.PresentRefreshCount; have = 1;
    if (!win0) { win0 = now_us; sync0 = st.SyncRefreshCount; qpc0 = st.SyncQPCTime; return; }
    if (now_us - win0 < 10000000ull) return;
    const u32 n = hist[0] + hist[1] + hist[2] + hist[3];
    double hz = 0;
    LARGE_INTEGER qf;
    if (QueryPerformanceFrequency(&qf) && st.SyncQPCTime.QuadPart > qpc0.QuadPart)
        hz = (double)(st.SyncRefreshCount - sync0) * (double)qf.QuadPart /
             (double)(st.SyncQPCTime.QuadPart - qpc0.QuadPart);
    u32 top = 0; for (int i = 0; i < 4; i++) if (hist[i] > top) top = hist[i];
    char hzs[24];   /* the window moved to another monitor: its refresh count starts elsewhere */
    if (hz >= 20.0 && hz <= 500.0) snprintf(hzs, sizeof hzs, "%.1f Hz", hz);
    else snprintf(hzs, sizeof hzs, "monitor changed");
    /* In a window the statistics are the compositor's (clocked by the primary
     * monitor, often only a few frames in a window resolvable): no line then. */
    if (n >= 100) printf("[pacing] %s, %.1f frames/s shown; refreshes per frame: 1 x%u, 2 x%u, 3 x%u, 4+ x%u"
                         " (unsampled %u): %s\n", hzs, (double)(n + unsampled) * 1e6 / (double)(now_us - win0),
                         hist[0], hist[1], hist[2], hist[3], unsampled, top * 100u >= n * 98u ? "even" : "uneven");
    memset(hist, 0, sizeof hist); unsampled = 0;
    win0 = now_us; sync0 = st.SyncRefreshCount; qpc0 = st.SyncQPCTime;
}

static HRESULT ld_present(IDXGISwapChain3* sc)
{
    extern unsigned long long ps3_qpc_us(void);
    ldr_wait_last_submit();   /* LD_RECORDER=2: the frame's lists are on the queue first */
    const unsigned long long t0 = ps3_qpc_us();
    if (g_ld_hitch_ms < 0) { const char* e = getenv("LD_HITCH_MS"); g_ld_hitch_ms = e ? atoi(e) : 40; }
    t_ld_ht_thread = 1;
    { static unsigned long long last;
      if (last) {
          const long long gap = (long long)(t0 - last);
          if (gap > g_ld_gap_max_us) g_ld_gap_max_us = gap;
          if (gap > 50000) g_ld_hitches++;
          g_ld_gap_hist[gap < 20000 ? 0 : gap < 34000 ? 1 : gap < 50000 ? 2 : gap < 67000 ? 3 : gap < 100000 ? 4 : 5]++;
      }
      ld_hitch_frame(last ? (long long)(t0 - last) : 0);
      last = t0; }
    const int vsync = g_ld_vsync && !g_ps3_load_turbo;   /* LD_TURBO_LOAD: never wait on the loading screen */
    { extern void cellGcm_pace_note_present(void); cellGcm_pace_note_present(); }   /* [pace] (cellGcmSys.c) */
    if (s_fsr3.on || s_fsr3.scale_on) fsr3_fg_before_present(s_fsr3_game_frame && !g_ps3_load_turbo);   /* FSR3_FG / FSR3_SCALE */
    const HRESULT hr = sc->lpVtbl->Present(sc, vsync ? 1 : 0,
                                           !vsync && g_ld_tearing ? DXGI_PRESENT_ALLOW_TEARING : 0);
    ld_pacing_note(sc, vsync, t0);
    g_ld_present_us += (long long)(ps3_qpc_us() - t0);
    return hr;
}
#define MAX_SURFACES     64
/* The texture cache's capacity; how much of it is used is LD_TEX_CACHE_CAP
 * and LD_TEX_CACHE_MB (texture_srv_slot). */
#define MAX_TEXTURES     4096
#define MAX_RETIRED_TEXTURES 4096
#define MAX_VTEX         64
/* Sampler states kept; how many are used is LD_SMP_CACHE (sampler_slot). */
#define MAX_SAMPLERS     2048
/*
 * A full live boot carries shader pairs from startup movies, menus, and AUTH
 * into the orphanage.  The old 256-entry cap was already exhausted there,
 * causing 155/328 sampled a010 groups to return NULL from get_pso().  The
 * one-frame reference alone uses 197 pairs.  A full visible boot through
 * orphanage and into Akiyama measured 2,296 distinct requested PSO keys before
 * the first presentation stall, so use the next power of two with headroom.
 */
/* Was 8192: a ~20-minute session in later chapters needs more than that (8068
 * of 8192 came from the disk library: real variants, not a leak), and once
 * full every draw needing a new pipeline was dropped -- up to 22% of draws,
 * old frames showing through the holes. */
#define MAX_PSOS         32768
#define FORMER_MAX_SHADER_BLOBS 2048
#define MAX_SHADER_BLOBS 16384   /* 8192 before LD_PSO_RT_FREE; 10,176 shipped recipes use 6,867 texts */
#define MAX_REJECTED_PSO_KEYS 8192
#define UPLOAD_SIZE      (64u * 1024 * 1024)
#define SHADER_DISK_CACHE_MAGIC   0x43535A59u /* "YZSC" */
/* v2: OP_KIL now emits discard (was a dropped TODO) — cached v1 pixel
 * shaders would silently keep the old no-discard codegen. */
#define SHADER_DISK_CACHE_VERSION 2u
#define SHADER_DISK_CACHE_MAX_BLOB (4u * 1024u * 1024u)

#define SRV_WHITE        0
#define SRV_SURFACE_BASE 1
#define SRV_ZDEPTH_BASE  (SRV_SURFACE_BASE + MAX_SURFACES)
#define SRV_TEXTURE_BASE (SRV_ZDEPTH_BASE + MAX_SURFACES)
#define SRV_VTEX_BASE    (SRV_TEXTURE_BASE + MAX_TEXTURES)
#define SRV_HEAP_SLOTS   (SRV_VTEX_BASE + MAX_VTEX)
#define SRV_DEPTH_SOURCE_BASE SRV_HEAP_SLOTS
#define UAV_ZDEPTH_BASE   (SRV_DEPTH_SOURCE_BASE + MAX_SURFACES)
/* Per-surface copy a draw samples when it reads its own render target. */
#define SRV_FEEDBACK_BASE (UAV_ZDEPTH_BASE + MAX_SURFACES)
/* A zeta's depth packed as the bytes an ARGB8 read of it sees (zdepth_pack). */
#define SRV_ZPACK_BASE    (SRV_FEEDBACK_BASE + MAX_SURFACES)
#define UAV_ZPACK_BASE    (SRV_ZPACK_BASE + MAX_SURFACES)
/* A colour surface read back as Y16_X16_FLOAT (surface_half2_srv). */
#define SRV_HALF2_BASE    (UAV_ZPACK_BASE + MAX_SURFACES)
#define UAV_HALF2_BASE    (SRV_HALF2_BASE + MAX_SURFACES)
/* A surface read through its texture's component remap (ld_surface_remap_srv). */
#define SRV_REMAP_BASE    (UAV_HALF2_BASE + MAX_SURFACES)
/* The renderer's own full-screen passes (ld_pp_*): an LD_PP_* target's view
 * at SRV_PP_BASE + k (its RTV at LD_RTV_PP + k), a copy's source after them. */
#define SRV_PP_BASE       (SRV_REMAP_BASE + MAX_SURFACES)
#define SRV_CPU_HEAP_SLOTS (SRV_PP_BASE + 21)   /* LD_AO: + its target and depth view; + 1 the trophy popup (host/trophies) */
#define LD_RTV_PP         (LD_SWAP_BUFFERS + MAX_SURFACES)
#define LD_PP_FMTS        8
enum { LD_PP_COLOR, LD_PP_EDGES, LD_PP_BLEND, LD_PP_OUT, LD_PP_MOVIE, LD_PP_SHARP, LD_PP_RESOLVE, LD_PP_AREA,
       LD_PP_SEARCH, LD_PP_HOLE0, LD_PP_HOLE1, LD_PP_HOLE2, LD_PP_HOLE3, LD_PP_HOLE_CUR, LD_PP_AO, LD_PP_UI /* the in-game overlay's layer under frame generation */, LD_PP_N };
#define SRV_TABLE_SIZE   16
/* Tables between two GPU syncs. 4096 wrapped about twice a frame in God of
 * War: Ascension's levels, and each wrap waits for the GPU. 32768 x 16 is
 * 524288 descriptors, within any D3D12 tier's shader-visible heap. */
#define SRV_RING_TABLES  32768

#define SMP_DEFAULT      0
#define SMP_CACHE_SLOTS  MAX_SAMPLERS
#define SMP_TABLE_SIZE   16
/* A shader-visible SAMPLER heap is hard-capped at 2048 descriptors by D3D12
 * (D3D12_MAX_SHADER_VISIBLE_SAMPLER_HEAP_SIZE). SMP_RING_TABLES*SMP_TABLE_SIZE
 * must stay <= 2048, else CreateDescriptorHeap fails. Identical sampler
 * tables share entries, so this is 128 unique tables between GPU flushes. */
#define SMP_RING_TABLES  128

#define CB_BLOCK_BYTES   ((512 + 2) * 16)
#define CB_BLOCK_ALIGNED ((CB_BLOCK_BYTES + 255) & ~255u)
/* Vertex constant blocks between two GPU syncs (a draw whose constants match
 * the previous draw's reuses its block, see the upload). */
#define CB_RING_BLOCKS   8192
#define CB_RING_BYTES    (CB_BLOCK_ALIGNED * CB_RING_BLOCKS)
#define PS_CB_RING_BYTES CB_RING_BYTES
#define LD_VARIANT_SET_CAPACITY (MAX_SHADER_BLOBS * 2u)

#define VERT_STRIDE      (16 * 4 * 4)   /* 16 attrs * float4                  */
#define VERT_BUFFER_SIZE (256u * 1024u * 1024u)
#define INDEX_BUFFER_SIZE (64u * 1024u * 1024u)
#define LD_INVALID_SURFACE 0xFFFFFFFFu

/* gcm texture format bytes (mirror rsx_dispatch.h) */
#define TEX_FMT_B8         0x81
#define TEX_FMT_A1R5G5B5   0x82
