typedef struct {
    u32 location, offset;
    ID3D12Resource* tex;
    u32 w, h;
    DXGI_FORMAT fmt;
    u8 sc;                    /* LD_RES_SCALE: host pixels per guest pixel (w, h are guest) */
    ID3D12Resource* fb_tex;   /* feedback copy, see surface_feedback_srv */
    ID3D12Resource* wb;       /* readback for a guest-read target, see ld_wb_record */
    ID3D12Resource* half2;    /* R16G16_FLOAT view of its bytes, see surface_half2_srv */
    u32 half2_w, half2_h;
    int wb_dirty;
    ID3D12Resource* wbp[2];   /* deferred write-back, one per async present pair (LD_WB_DEFER) */
    int wbp_rec[2];
    /* LD_SURF_ALIAS: the colour pitch in the surface's key (0: swizzled or
     * unknown, keyed on the size as well) and the frame it was last bound,
     * sampled, copied or presented (eviction picks the oldest). */
    u32 pitch;
    u32 last_use;
    u32 color_seq;            /* LD_ZREAD_RECENT: g_ld_write_seq of its last colour write */
    /* LD_SURF_GUEST_NEWER: the frame of its last GPU write, the page
     * generation its memory had then, and this frame's verdict. */
    u32 gpu_frame, ww_gen, ww_check_frame;
    u8 ww_init, ww_newer;
#if !defined(YZ_PERF_CLEAN)
    u32 resource_serial;
    u32 last_write_generation;
    u32 last_write_kind;
    u32 last_create_generation;
    u32 last_draw_generation;
    u32 last_clear_generation;
    u32 last_copy_generation;
    u32 last_blit_generation;
    u32 last_resolve_generation;
    u32 last_other_generation;
    u32 last_guest_blit_generation;
    u32 last_present_copy_generation;
#endif
} surface_t;
typedef struct {
    u32 location, offset, pitch, width, height;
    int valid;
    int resolve_src;   /* surface slot + 1 a scaled blit resolves into this buffer; 0 = none */
} display_buffer_t;
typedef struct {
    u32 location, offset;
    ID3D12Resource* tex;
    ID3D12Resource* snapshot;
    u32 w, h;
    u32 snapshot_w, snapshot_h;
    u8 sc;                     /* LD_RES_SCALE: as surface_t's; w, h, snapshot_w/h are guest */
    D3D12_RESOURCE_STATES snapshot_state;
    int cleared;
    int had_write;
    int snapshot_valid;
    u64 draws;
    u64 depth_test_draws;
    u64 depth_write_draws;
    u64 depth_both_draws;
    int reject_logged;
    u32 snapshot_gen;          /* bumped each time the snapshot is refreshed */
    ID3D12Resource* packed;    /* RGBA8: the depth as an ARGB8 read sees it */
    u32 packed_w, packed_h, packed_remap, packed_gen;
    int packed_valid;
    u32 depth_seq;             /* LD_ZREAD_RECENT: g_ld_write_seq of its last depth write */
} zdepth_t;
/* LD_RES_SCALE: host pixels per guest pixel (see g_ld_rs). */
static inline u32 ld_sc(const surface_t* s) { return s->sc ? s->sc : 1u; }
static inline u32 ld_zsc(const zdepth_t* z) { return z->sc ? z->sc : 1u; }
typedef struct {
    u32 location, offset, format, width, height, pitch, remap;
    u32 cubemap;
    ID3D12Resource* tex;
    u64 content_hash;
    u32 last_hash_frame;
    u64 last_use_serial;
    u32 dirty_gen;             /* page generation when last hashed (ld_dirty_sync); 0 = unknown */
    u32 dynamic_frame;         /* LD_TEX_INTRAFRAME: last frame its content changed; 0 = never */
    u32 dimension, depth, mipmaps;   /* LD_TEX_KEY_FULL: also in the key */
    u64 bytes;                 /* the resource's size, roughly (LD_TEX_CACHE_MB) */
    u32 io_gen;                /* g_gcm_io_remap_gen when last checked (main-memory entries) */
    u32 content_crc;           /* LD_TEX_DEDUP: CRC-32C of the source bytes it was decoded from */
    u32 crc_valid;             /* content_crc belongs to content_hash (0: unknown, never shared from) */
} texcache_t;
typedef struct {
    u32 location, offset, format, width, height, pitch;
    ID3D12Resource* tex;
    u64 content_hash;
    u32 last_hash_frame;
} vtexcache_t;
typedef struct {
    u64 key; ID3D12PipelineState* pso;
    unsigned long long pending_us;   /* LD_PSO_ASYNC: when it was queued (LD_PSO_MAX_SKIP_MS) */
    struct ld_pso_job* job;          /* its job while still queued (s_psoq.lock), else NULL */
    volatile LONG slow;              /* LD_PSO_WAIT_FAST: its builder compiles or creates it (not a quick load) */
    LONG dq_pos;                     /* LD_PSO_RT_FREE: its request's position + 1 (0: none) */
    u32 req_frame;                   /* the frame it was asked for in */
    u32 urged;                       /* LD_PSO_URGENT: put in the urgent lane */
    u32 fz_frame;                    /* LD_FLOOR_ZERO: the frame + 1 a skipped draw of it was noted in */
    struct ld_pso_job* volatile rjob;   /* LD_FLOOR_DEFER: a failed build's request, kept to build it again */
    volatile LONG fails;             /* LD_FLOOR_DEFER: builds of it that failed */
    u32 dd_stamp;                    /* LD_FLOOR_DEFER: the resolve that listed it */
    volatile LONG dd_flags;          /* LD_FLOOR_DEFER: 1 a duplicate was built, 2 given up (stuck), 4 cannot be built */
    ID3D12PipelineState* volatile uber;   /* UBER: the ubershader pipeline for this slot's state: NULL none,
                                           * LD_PSO_PENDING being made, else ready */
    D3D12_GPU_VIRTUAL_ADDRESS uber_va;    /* UBER: the program table (root parameter 5, b2) */
    /* UBER2 (2026-11-08): the vertex bytecode check -- hash|1 of the vertex shader bytecode the twin uses and the one the
     * specialised build used (bit 1 of each: IEEE-strict), compared once both are known (ub_vs_done) */
    volatile LONG64 ub_vsh, sp_vsh;
    volatile LONG ub_vs_done;
    u32 ub_deny_frame;                    /* UBER2 budget: frame + 1 in which this slot's draws wait as without a twin */
    u32 dd_k;                             /* UBER2: its index in the waiting flush's list of slots */
    u32 ub_flags;                         /* UBER2: 1 its state tests depth EQUAL (LD_UBER_FORCE_EQ, LD_UBER_EQ) */
    u32 ub_ops;                           /* UBER2: the program's decoded operations (the interpreter's cost per pixel) */
    D3D12_GPU_VIRTUAL_ADDRESS uber_vva;   /* UBER3 VS: the vertex program table (root parameter 6, b3); 0 = the twin uses the specialised vertex shader */
} psocache_t;

/* Hash index over g.psos (which only ever grows): each slot holds a g.psos
 * position + 1, 0 = empty. The cache was searched linearly on every draw,
 * thousands of entries deep once a level has been running for a while. */
/* The current draw's depth-compare scales (texture size / zeta snapshot size),
 * set by get_pso and uploaded with the pixel constants when the shader reads
 * them from fp_shadow_scale. */
static int   g_ld_cur_shadow_cb;
static float g_ld_cur_shadow_scale[16][2];
/* LD_SHADOW_EDGE (default on). A depth-compare texture smaller than the zeta
 * snapshot it reads (fp_shadow_scale < 1) took the snapshot's texels past its
 * own edge: the sampler clamps or applies the border only at the snapshot's
 * edge. The RSX applies the texture's address mode at the texture's edge.
 * God of War: Ascension's shadow buffer at 0x1550000 changes size every frame
 * (1382x736 to 1408x1408) and the snapshot only grows, so the PCF taps along
 * a shadow map's right and bottom edges, and any coordinate past them, read
 * depth from outside the map (the clear value, or another pass's depth).
 * Buffered pixel constants only: fp_shadow_scale[u].z carries the modes
 * (bit 0/1: U/V clamp to the texture's edge, bit 2/3: U/V border), .w the
 * border depth; ld_shadow_edge_patch makes each PCF tap honour them. Other
 * modes (wrap, mirror) are left to the sampler, as before.
 * LD_SHADOW_EDGE=0: as before (.zw stay 1). */
static float g_ld_cur_shadow_edge[16][2];
static int ld_shadow_edge_on(void)
{
    static int on = -1;
    if (on < 0) { const char* e = getenv("LD_SHADOW_EDGE"); on = !(e && e[0] == '0'); }
    return on;
}
/* LD_SHADOW_EDGE: route the four PCF taps of unit su's helper (the
 * decompiler's fp_shadow_helper text, linear filtering) through
 * _rsx_shadow_tap<su>, which clamps the tap's texel to the texture's last
 * texel or compares against the border depth. 0 if the text was not found
 * (nothing changed then) or does not fit. */
static int ld_shadow_edge_patch(char* ps, size_t cap, u32 su, u32 cube_mask)
{
    char tex[32], head[64], fn[1024], old[256], neu[160];
    snprintf(tex, sizeof tex, cube_mask ? "rsx_tex%u" : "rsx_tex[%u]", su);
    snprintf(head, sizeof head, "float4 _rsx_shadow%u(float3 coordinate) {", su);
    char* h = strstr(ps, head);
    if (!h) return 0;
    for (u32 tap = 0; tap < 4; tap++) {   /* all four first: all or nothing */
        snprintf(old, sizeof old,
            "    float d%u = %s.SampleLevel(rsx_samp[%u], (base + float2(%s, %s)) / size, 0.0).r;\n"
            "    float c%u = _rsx_shadow_cmp%u(reference, d%u);\n",
            tap, tex, su, (tap & 1) ? "1.5" : "0.5", (tap & 2) ? "1.5" : "0.5", tap, su, tap);
        if (!strstr(h, old)) return 0;
    }
    snprintf(fn, sizeof fn,
        "float _rsx_shadow_tap%u(float reference, float2 p, float2 size) {\n"
        "    float4 e = fp_shadow_scale[%u];\n"
        "    float2 t = p - 0.5;\n"
        "    float2 c = clamp(t, 0.0, floor(e.xy * size + 0.5) - 1.0);\n"
        "    uint m = (uint)e.z;\n"
        "    if (((m & 4u) != 0u && c.x != t.x) || ((m & 8u) != 0u && c.y != t.y))\n"
        "        return _rsx_shadow_cmp%u(reference, e.w);\n"
        "    float2 q = float2((m & 1u) != 0u ? c.x : t.x, (m & 2u) != 0u ? c.y : t.y);\n"
        "    return _rsx_shadow_cmp%u(reference, %s.SampleLevel(rsx_samp[%u], (q + 0.5) / size, 0.0).r);\n"
        "}\n", su, su, su, su, tex, su);
    size_t tl = strlen(ps);
    const size_t fl = strlen(fn);
    if (tl + fl + 1 > cap) return 0;
    memmove(h + fl, h, tl - (size_t)(h - ps) + 1);
    memcpy(h, fn, fl);
    h += fl;
    for (u32 tap = 0; tap < 4; tap++) {
        snprintf(old, sizeof old,
            "    float d%u = %s.SampleLevel(rsx_samp[%u], (base + float2(%s, %s)) / size, 0.0).r;\n"
            "    float c%u = _rsx_shadow_cmp%u(reference, d%u);\n",
            tap, tex, su, (tap & 1) ? "1.5" : "0.5", (tap & 2) ? "1.5" : "0.5", tap, su, tap);
        snprintf(neu, sizeof neu, "    float c%u = _rsx_shadow_tap%u(reference, base + float2(%s, %s), size);\n",
                 tap, su, (tap & 1) ? "1.5" : "0.5", (tap & 2) ? "1.5" : "0.5");
        char* u = strstr(h, old);
        const size_t ol = strlen(old), nl = strlen(neu);
        tl = strlen(ps);
        memmove(u + nl, u + ol, tl - (size_t)(u - ps) - ol + 1);   /* shorter: always fits */
        memcpy(u, neu, nl);
    }
    return 1;
}
/* Texture units the current fragment program samples (set by get_pso). */
static u32   g_ld_cur_fp_units = 0xFFFFu;
/* LD_SURF_ALIAS: units whose coordinates the current pipeline multiplies by
 * fp_shadow_scale[u] (set by get_pso, see ld_surf_scale_units). */
static u32   g_ld_cur_surf_units;
/* LD_FULLRES_FX: units whose multi-tap filters get every host texel (get_pso). */
static u32   g_ld_cur_fx_units;
/* LD_FULLRES_FX round 2: per unit of a 1-tap downsample read, the source /
 * target size ratio in x and y and the source surface's scale (0: the unit is
 * no downsample source); key material. */
static float g_ld_cur_fx_ds[16][3];

static int s_gp_probe;   /* GP_PULL: get_pso_full answers NULL instead of waiting for a pipeline being built */
#define PSO_INDEX_BITS 16u   /* 65536 slots for at most MAX_PSOS (32768) */
static u32 s_pso_index[1u << PSO_INDEX_BITS];
static inline u32 pso_index_slot(u64 key)
{
    return (u32)((key * 0x9E3779B97F4A7C15ull) >> (64u - PSO_INDEX_BITS));
}
