static void ld_fill(u8* img, u32 w, u32 h, int x0, int y0, int x1, int y1, const u8 c[3])
{
    if (x0 < 0) x0 = 0; if (y0 < 0) y0 = 0;
    if (x1 > (int)w) x1 = (int)w; if (y1 > (int)h) y1 = (int)h;
    for (int y = y0; y < y1; y++)
        for (int x = x0; x < x1; x++) { u8* p = img + ((size_t)y * w + (size_t)x) * 4; p[0] = c[0]; p[1] = c[1]; p[2] = c[2]; p[3] = 255; }
}
/* One line of text, centred at row y, s pixels per font pixel. */
static void ld_text(u8* img, u32 w, u32 h, int y, int s, const char* t, const u8 c[3])
{
    const int n = (int)strlen(t), x0 = ((int)w - (n * 6 - 1) * s) / 2;
    for (int i = 0; i < n; i++) {
        const u8* rows = NULL;
        for (size_t k = 0; k < sizeof k_ld_font / sizeof k_ld_font[0]; k++)
            if (k_ld_font[k].c == t[i]) { rows = k_ld_font[k].rows; break; }
        if (!rows) continue;   /* a space, or a character the font lacks */
        for (int r = 0; r < 7; r++)
            for (int col = 0; col < 5; col++)
                if (rows[r] & (0x10 >> col))
                    ld_fill(img, w, h, x0 + (i * 6 + col) * s, y + r * s, x0 + (i * 6 + col + 1) * s, y + (r + 1) * s, c);
    }
}
void rsx_live_draw_present_progress(unsigned done, unsigned total)
{
    static u8* img; static u32 iw, ih;
    if (!g.ready || !g.width || !g.height) return;
    if (!img || iw != g.width || ih != g.height) {
        free(img); iw = g.width; ih = g.height;
        img = (u8*)malloc((size_t)iw * ih * 4);
        if (!img) return;
    }
    static const u8 bg[3] = {10, 8, 8}, ink[3] = {226, 196, 140}, dim[3] = {150, 130, 110},
                    rail[3] = {48, 36, 34}, fill[3] = {176, 32, 18};
    ld_fill(img, iw, ih, 0, 0, (int)iw, (int)ih, bg);
    const int s = (int)ih / 180 > 1 ? (int)ih / 180 : 1;   /* 4 at 720 lines */
    char line[64];
    ld_text(img, iw, ih, (int)ih * 36 / 100, s, "COMPILING SHADERS", ink);
    const unsigned pct = total ? (unsigned)((unsigned long long)done * 100u / total) : 0u;
    snprintf(line, sizeof line, "%u / %u  (%u%%)", done, total, pct);
    ld_text(img, iw, ih, (int)ih * 46 / 100, s > 1 ? s - 1 : 1, line, ink);
    const int bx0 = (int)iw / 5, bx1 = (int)iw - (int)iw / 5, by0 = (int)ih * 55 / 100, by1 = by0 + (int)ih / 36;
    ld_fill(img, iw, ih, bx0, by0, bx1, by1, rail);
    ld_fill(img, iw, ih, bx0, by0, bx0 + (int)((long long)(bx1 - bx0) * (total ? done : 0) / (total ? total : 1)), by1, fill);
    ld_text(img, iw, ih, (int)ih * 63 / 100, s > 2 ? s - 2 : 1, "ONCE AFTER AN INSTALL OR UPDATE. THE GAME STARTS WHEN THIS IS DONE.", dim);
    s_ld_hitch_quiet = 1;   /* LD_HITCH_MS: these 10 Hz frames are not game frames */
    rsx_live_draw_present_rgba(img, iw, ih);
    s_ld_hitch_quiet = 0;
}

/* Present a host-decoded RGBA8 frame to the window: copy it straight into the
 * swap-chain backbuffer (both R8G8B8A8_UNORM at the swap size) and Present.
 * The frame is clamped to the backbuffer size. Call from a single thread with
 * movie mode on (so guest draws don't touch g.list). */
void rsx_live_draw_present_rgba(const uint8_t* rgba, u32 w, u32 h)
{
    const int composite = ld_movie_composite_ui_enabled();
    const int serialized = composite || g_ld_debug_layer_enabled;
    if (serialized) {
        InterlockedExchange(&g_ld_host_waiting, 1);
        AcquireSRWLockExclusive(&g_ld_access_lock);
    }
    if (!g.ready || !rgba) {
        if (serialized) {
            ReleaseSRWLockExclusive(&g_ld_access_lock);
            InterlockedExchange(&g_ld_host_waiting, 0);
        }
        return;
    }
    if (composite && !ld_movie_overlay_ensure()) {
        ReleaseSRWLockExclusive(&g_ld_access_lock);
        InterlockedExchange(&g_ld_host_waiting, 0);
        return;
    }
    if (w > g.width)  w = g.width;
    if (h > g.height) h = g.height;
    const u32 pitch = (w * 4 + 255) & ~255u;          /* D3D12 copy pitch align */
    if ((UINT64)pitch * h > UPLOAD_SIZE) {
        if (serialized) {
            ReleaseSRWLockExclusive(&g_ld_access_lock);
            InterlockedExchange(&g_ld_host_waiting, 0);
        }
        return;
    }

    u8* host_upload = composite ? g.movie_upload_mapped : g.upload_mapped;
    for (u32 y = 0; y < h; y++) {
        u8* dstrow = host_upload + (size_t)y * pitch;
        memcpy(dstrow, rgba + (size_t)y * w * 4, (size_t)w * 4);
        if (composite && g.movie_overlay_valid && g.movie_overlay_rgba &&
            g.movie_overlay_mask) {
            const u8* ov = g.movie_overlay_rgba + (size_t)y * g.width * 4;
            const u8* mask =
                g.movie_overlay_mask + (size_t)y * g.width;
            for (u32 x = 0; x < w; x++, ov += 4) {
                const int coverage = mask[x];
                if (!coverage) continue;
                u8* out = dstrow + (size_t)x * 4;
                if (coverage == 1) {
                    out[0] = (u8)((out[0] * 64 + 127) / 255);
                    out[1] = (u8)((out[1] * 64 + 127) / 255);
                    out[2] = (u8)((out[2] * 64 + 127) / 255);
                    continue;
                }
                const int white = ov[0] > ov[1]
                    ? (ov[0] > ov[2] ? ov[0] : ov[2])
                    : (ov[1] > ov[2] ? ov[1] : ov[2]);
                for (int c = 0; c < 3; c++) {
                    const int v =
                        (white * coverage +
                         out[c] * (255 - coverage) + 127) / 255;
                    out[c] = (u8)v;
                }
                out[3] = 255;
            }
        }
    }

    const u32 bbi = g.swap->lpVtbl->GetCurrentBackBufferIndex(g.swap);
    ID3D12Resource* bb = g.backbuf[bbi];

    D3D12_RESOURCE_BARRIER b = {0};
    b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource = bb;
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_PRESENT;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_DEST;
    LD_CL(ResourceBarrier, 1, &b);

    /* LD_RES_SCALE: the swap chain's buffer is larger than the canvas; the
     * frame goes into a canvas-sized texture and is drawn over the buffer. */
    const int scaled = g.bb_w != g.width || g.bb_h != g.height;
    if (scaled && !ld_pp_target(LD_PP_MOVIE, g.width, g.height, DXGI_FORMAT_R8G8B8A8_UNORM)) {
        if (serialized) {
            ReleaseSRWLockExclusive(&g_ld_access_lock);
            InterlockedExchange(&g_ld_host_waiting, 0);
        }
        return;
    }
    ID3D12Resource* movie = scaled ? s_pp.t[LD_PP_MOVIE].res : bb;
    if (scaled) {
        b.Transition.pResource = movie;
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE;
        LD_CL(ResourceBarrier, 1, &b);
    }
    D3D12_TEXTURE_COPY_LOCATION dst = {0}, src = {0};
    dst.pResource = movie; dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX; dst.SubresourceIndex = 0;
    src.pResource = composite ? g.movie_upload : g.upload;
    src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
    src.PlacedFootprint.Offset = 0;
    src.PlacedFootprint.Footprint.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    src.PlacedFootprint.Footprint.Width = w;
    src.PlacedFootprint.Footprint.Height = h;
    src.PlacedFootprint.Footprint.Depth = 1;
    src.PlacedFootprint.Footprint.RowPitch = pitch;
    LD_CL(CopyTextureRegion, &dst, 0, 0, 0, &src, NULL);
    if (scaled) {
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
        b.Transition.StateAfter = D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE;
        LD_CL(ResourceBarrier, 1, &b);
        b.Transition.pResource = bb;
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
        b.Transition.StateAfter = D3D12_RESOURCE_STATE_PRESENT;
        LD_CL(ResourceBarrier, 1, &b);
        /* ld_pp_present: PRESENT -> drawn -> overlay -> PRESENT. */
        if (!ld_pp_present(bb, bbi, movie, D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE, g.width, g.height,
                           w, h, w, h, 0)) {
            static u32 logs = 0;
            if (logs++ < 4) fprintf(stderr, "[pp] movie present pass failed\n");
        }
    } else {
    const int menu = ld_menu_present(0, 0, 0, 0);               /* in-game menu: this frame's work; 1 = draw the panel */
    if (s_credit.state >= 0 || menu) {                          /* the credit, as on game frames (w x h at 0,0) */
        ld_pp_barrier(bb, D3D12_RESOURCE_STATE_COPY_DEST, D3D12_RESOURCE_STATE_RENDER_TARGET);
        ld_credit_draw(bbi, w < g.bb_w ? w : g.bb_w, h < g.bb_h ? h : g.bb_h);
        if (menu) ld_menu_present(bbi, w < g.bb_w ? w : g.bb_w, h < g.bb_h ? h : g.bb_h, 2);
        ld_pp_barrier(bb, D3D12_RESOURCE_STATE_RENDER_TARGET, D3D12_RESOURCE_STATE_COPY_DEST);
    }
    ld_w2_init_once();   /* W2_INIT (host/w2i) */
    ld_fgui_perf(bb);   /* ovl3: the FPS counter (into the overlay's layer under frame generation) */

    b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_PRESENT;
    LD_CL(ResourceBarrier, 1, &b);
    }

    ld_flush(LD_FLUSH_MOVIE_PRESENT);
    {
        g_ld_present_movie++;
        ld_turbo_update(1);
        s_fsr3_game_frame = 0;   /* FSR3_FG: no generation on movies */
        const HRESULT present_hr = ld_present(g.swap);
        if (SUCCEEDED(present_hr))
            ld_present_measure_record(g_ld_frames);
        else {
            fprintf(stderr,
                    "[d3d-fail] movie Present hr=0x%08lX frame=%u\n",
                    (unsigned long)present_hr, g_ld_frames);
            ld_dump_dred("MoviePresent", present_hr);
            g.ready = 0;
        }
    }
    if (serialized) {
        ReleaseSRWLockExclusive(&g_ld_access_lock);
        InterlockedExchange(&g_ld_host_waiting, 0);
    }
}

/* Env-gated (RSX_DUMP) framebuffer dump: read the current color surface back
 * and write a binary PPM. Self-contained -- creates + releases its own readback
 * buffer, so no init/struct changes. Uses g.list which ld_flush leaves open. */
/* Readback texel -> 8-bit RGB.  This title renders HDR into FP16 targets, so a
 * dump has to tone it down rather than reinterpret the bytes.  Reinhard keeps
 * the whole range visible without pretending to match the guest tonemapper. */
static void ld_dump_texel_rgb(const u8* p, int fp16, u8* out)
{
    if (!fp16) { out[0] = p[0]; out[1] = p[1]; out[2] = p[2]; return; }
    for (int c = 0; c < 3; c++) {
        const u16 h = (u16)(p[c * 2] | (p[c * 2 + 1] << 8));
        const int ex = (h >> 10) & 0x1F, ma = h & 0x3FF;
        float f;
        if (ex == 0)       f = (float)ma * (1.0f / 16384.0f) * (1.0f / 64.0f);
        else if (ex == 31) f = 65504.0f;
        else { f = 1.0f + (float)ma / 1024.0f;
               int k = ex - 15;
               while (k > 0) { f *= 2.0f; k--; }
               while (k < 0) { f *= 0.5f; k++; } }
        if (h & 0x8000) f = 0.0f;
        f = f / (1.0f + f);                          /* Reinhard */
        out[c] = (u8)(f * 255.0f + 0.5f);
    }
}

/* --record: when set, ld_dump_surface_ppm appends to this ffmpeg pipe instead
 * of opening `path`, and skips its per-dump diagnostics (every frame goes
 * through here while recording). */
static FILE* g_ld_record_to;

static u64 ld_dump_surface_ppm(const char* path, const surface_t* surface)
{
    ID3D12Resource* rt = surface ? surface->tex : NULL;
    if (!rt) return UINT64_MAX;
    const u32 width = surface->w * ld_sc(surface);    /* LD_RES_SCALE: every host pixel */
    const u32 height = surface->h * ld_sc(surface);
    if (!width || !height) return UINT64_MAX;
    const int fp16 = surface->fmt == DXGI_FORMAT_R16G16B16A16_FLOAT;
    const u32 texel = fp16 ? 8u : 4u;
    const u32 pitch = (width * texel + 255) & ~255u;             /* 256-align */
    const UINT64 rb_size = (UINT64)pitch * height;

    D3D12_HEAP_PROPERTIES hp = {0}; hp.Type = D3D12_HEAP_TYPE_READBACK;
    D3D12_RESOURCE_DESC bd = {0};
    bd.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER; bd.Width = rb_size;
    bd.Height = 1; bd.DepthOrArraySize = 1; bd.MipLevels = 1;
    bd.Format = DXGI_FORMAT_UNKNOWN; bd.SampleDesc.Count = 1;
    bd.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
    ID3D12Resource* rb = NULL;
    if (FAILED(g.dev->lpVtbl->CreateCommittedResource(g.dev, &hp, D3D12_HEAP_FLAG_NONE, &bd,
            D3D12_RESOURCE_STATE_COPY_DEST, NULL, &IID_ID3D12Resource, (void**)&rb)))
        return UINT64_MAX;

    D3D12_RESOURCE_BARRIER b = {0};
    b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource = rt;
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_RENDER_TARGET;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
    LD_CL(ResourceBarrier, 1, &b);

    D3D12_TEXTURE_COPY_LOCATION src = {0}, dst = {0};
    src.pResource = rt; src.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX; src.SubresourceIndex = 0;
    dst.pResource = rb; dst.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
    dst.PlacedFootprint.Footprint.Format = surface->fmt;
    dst.PlacedFootprint.Footprint.Width = width;
    dst.PlacedFootprint.Footprint.Height = height;
    dst.PlacedFootprint.Footprint.Depth = 1;
    dst.PlacedFootprint.Footprint.RowPitch = pitch;
    LD_CL(CopyTextureRegion, &dst, 0, 0, 0, &src, NULL);

    b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_SOURCE;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_RENDER_TARGET;
    LD_CL(ResourceBarrier, 1, &b);

    ld_flush(LD_FLUSH_READBACK);                   /* copy completes on the GPU */

    u64 nonblack = UINT64_MAX;
    u64 fingerprint = 1469598103934665603ull;
    u8* px = NULL; D3D12_RANGE rr = {0, (SIZE_T)rb_size};
    if (SUCCEEDED(rb->lpVtbl->Map(rb, 0, &rr, (void**)&px))) {
        nonblack = 0;
        if (!g_ld_record_to) {   /* raw texels, to tell an FP16 target from 8-bit data read as one */
            const u8* r0 = px + (SIZE_T)(height / 4) * pitch + (width / 4) * texel;
            fprintf(stderr, "[dump-raw] %s fmt=%d texel=%u bytes:", path, (int)surface->fmt, texel);
            for (u32 bi = 0; bi < 16; bi++) fprintf(stderr, " %02X", r0[bi]);
            fprintf(stderr, "\n");
        }
        if (surface->fmt == DXGI_FORMAT_R32_FLOAT) {
            float vmin = 3.4e38f, vmax = -3.4e38f;
            for (u32 y = 0; y < height; y++)
                for (u32 x = 0; x < width; x++) {
                    float v; memcpy(&v, px + (SIZE_T)y * pitch + x * 4u, 4);
                    if (v == v && v > -3.0e38f && v < 3.0e38f) {
                        if (v < vmin) vmin = v;
                        if (v > vmax) vmax = v;
                    }
                }
            if (!g_ld_record_to) {
                fprintf(stderr, "[dump-r32] %s min=%g max=%g grid(16x9):\n", path, vmin, vmax);
                for (u32 gy = 0; gy < 9; gy++) {
                    fprintf(stderr, "[dump-r32]  ");
                    for (u32 gx = 0; gx < 16; gx++) {
                        float v; memcpy(&v, px + (SIZE_T)(gy * height / 9 + height / 18) * pitch +
                                            (gx * width / 16 + width / 32) * 4u, 4);
                        fprintf(stderr, " %9.4g", v);
                    }
                    fprintf(stderr, "\n");
                }
            }
            const float range = vmax > vmin ? vmax - vmin : 1.0f;
            for (u32 y = 0; y < height; y++)
                for (u32 x = 0; x < width; x++) {
                    u8* pixel = px + (SIZE_T)y * pitch + x * 4u;
                    float v; memcpy(&v, pixel, 4);
                    const u8 grey = (v == v) ? (u8)(255.0f * (v < vmin ? 0.0f : v > vmax ? 1.0f : (v - vmin) / range)) : 0;
                    pixel[0] = pixel[1] = pixel[2] = (v == v) ? grey : 0;
                    pixel[3] = 255;
                    if (v != v) pixel[0] = 255;   /* NaN: red */
                }
        }
        FILE* f = g_ld_record_to ? g_ld_record_to : fopen(path, "wb");
        if (f) {
            fprintf(f, "P6\n%u %u\n255\n", width, height);
            for (u32 y = 0; y < height; y++) {
                const u8* row = px + (SIZE_T)y * pitch;
                for (u32 x = 0; x < width; x++) {
                    const u8* pixel = row + x * texel;
                    u8 rgb[3]; ld_dump_texel_rgb(pixel, fp16, rgb);
                    if (rgb[0] || rgb[1] || rgb[2])
                        nonblack++;
                    fingerprint = fnv1a(rgb, 3, fingerprint);
                    fwrite(rgb, 1, 3, f);  /* RGBA->RGB */
                }
            }
            if (f != g_ld_record_to) {
                fclose(f);
                fprintf(stderr, "[live-draw] wrote %s\n", path);
                /* LD_DUMP_ALPHA=1: an 8-bit target's alpha too, as <path>.a.pgm
                 * (God of War: Ascension keeps the scene's HDR scale there). */
                static int alpha = -1;
                if (alpha < 0) { const char* e = getenv("LD_DUMP_ALPHA"); alpha = e && e[0] == '1'; }
                char apath[MAX_PATH * 2 + 8];
                FILE* af = NULL;
                if (alpha && texel == 4u && !fp16 && surface->fmt != DXGI_FORMAT_R32_FLOAT) {
                    snprintf(apath, sizeof apath, "%s.a.pgm", path);
                    af = fopen(apath, "wb");
                }
                if (af) {
                    fprintf(af, "P5\n%u %u\n255\n", width, height);
                    for (u32 y = 0; y < height; y++)
                        for (u32 x = 0; x < width; x++) fputc(px[(SIZE_T)y * pitch + x * 4u + 3u], af);
                    fclose(af);
                }
            }
        } else {
            for (u32 y = 0; y < height; y++) {
                const u8* row = px + (SIZE_T)y * pitch;
                for (u32 x = 0; x < width; x++) {
                    const u8* pixel = row + x * texel;
                    u8 rgb[3]; ld_dump_texel_rgb(pixel, fp16, rgb);
                    if (rgb[0] || rgb[1] || rgb[2])
                        nonblack++;
                    fingerprint = fnv1a(rgb, 3, fingerprint);
                }
            }
        }
        D3D12_RANGE wr = {0, 0};
        rb->lpVtbl->Unmap(rb, 0, &wr);
        g_ld_last_dump_fingerprint = fingerprint;
    }
    rb->lpVtbl->Release(rb);
    return nonblack;
}

/* LD_FRAME_COLOR (default on; =0 off): every 10 s, the average colour of the
 * presented picture's top band (where the sky usually is) and of its middle,
 * from 8 small 8x8 patches each, so a player's log says what they saw --
 * "the sky is not blue" becomes numbers. The patches are copied with that
 * frame's list into a small readback buffer and read 10 s later (the GPU has
 * long finished them), so nothing waits. */
static void ld_frame_color(const surface_t* s)
{
    enum { PATCH = 8, NPATCH = 16, SLOT = 4096 };
    static int on = -1;
    static ID3D12Resource* rb;
    static unsigned long long last_ms;
    static int pending, fp16_pending;
    if (on < 0) { const char* e = getenv("LD_FRAME_COLOR"); on = !(e && e[0] == '0'); }
    if (!on || !s || !s->tex) return;
    const unsigned long long now = GetTickCount64();
    if (last_ms && now - last_ms < 10000) return;
    last_ms = now;
    if (!rb) {
        D3D12_HEAP_PROPERTIES hp = {0}; hp.Type = D3D12_HEAP_TYPE_READBACK;
        D3D12_RESOURCE_DESC bd = {0};
        bd.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER; bd.Width = (UINT64)SLOT * NPATCH;
        bd.Height = 1; bd.DepthOrArraySize = 1; bd.MipLevels = 1; bd.Format = DXGI_FORMAT_UNKNOWN;
        bd.SampleDesc.Count = 1; bd.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        if (FAILED(g.dev->lpVtbl->CreateCommittedResource(g.dev, &hp, D3D12_HEAP_FLAG_NONE, &bd,
                D3D12_RESOURCE_STATE_COPY_DEST, NULL, &IID_ID3D12Resource, (void**)&rb))) { on = 0; return; }
    }
    if (pending) {   /* the patches copied 10 s ago */
        u8* px = NULL; D3D12_RANGE rr = {0, (SIZE_T)SLOT * NPATCH};
        if (SUCCEEDED(rb->lpVtbl->Map(rb, 0, &rr, (void**)&px))) {
            double sum[2][3] = {{0}};
            for (int p = 0; p < NPATCH; p++)
                for (int y = 0; y < PATCH; y++)
                    for (int x = 0; x < PATCH; x++) {
                        const u8* q = px + (SIZE_T)p * SLOT + (SIZE_T)y * 256u + (SIZE_T)x * (fp16_pending ? 8u : 4u);
                        for (int c = 0; c < 3; c++) {
                            double v;
                            if (fp16_pending) { u16 h; memcpy(&h, q + c * 2, 2); v = ld_half_to_float(h); }
                            else v = q[c] / 255.0;
                            sum[p / 8][c] += v;
                        }
                    }
            const double k = 255.0 / (8.0 * PATCH * PATCH);
            fprintf(stderr, "[frame-color] top %.0f %.0f %.0f, middle %.0f %.0f %.0f (RGB 0-255%s)\n",
                    sum[0][0] * k, sum[0][1] * k, sum[0][2] * k, sum[1][0] * k, sum[1][1] * k, sum[1][2] * k,
                    fp16_pending ? ", HDR target" : "");
            D3D12_RANGE wr = {0, 0};
            rb->lpVtbl->Unmap(rb, 0, &wr);
        }
        pending = 0;
    }
    const int fp16 = s->fmt == DXGI_FORMAT_R16G16B16A16_FLOAT;
    if (!fp16 && s->fmt != DXGI_FORMAT_R8G8B8A8_UNORM) return;
    const u32 w = s->w * ld_sc(s), h = s->h * ld_sc(s);
    if (w < 64 || h < 64) return;
    D3D12_RESOURCE_BARRIER b = {0};
    b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    b.Transition.pResource = s->tex;
    b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_RENDER_TARGET;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
    LD_CL(ResourceBarrier, 1, &b);
    for (int p = 0; p < NPATCH; p++) {
        const u32 x0 = (u32)((p % 8) * (w - PATCH) / 7), y0 = p < 8 ? h / 12 : h / 2;
        D3D12_TEXTURE_COPY_LOCATION src = {0}, dst = {0};
        src.pResource = s->tex; src.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
        dst.pResource = rb; dst.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
        dst.PlacedFootprint.Offset = (UINT64)p * SLOT;
        dst.PlacedFootprint.Footprint.Format = s->fmt;
        dst.PlacedFootprint.Footprint.Width = PATCH; dst.PlacedFootprint.Footprint.Height = PATCH;
        dst.PlacedFootprint.Footprint.Depth = 1; dst.PlacedFootprint.Footprint.RowPitch = 256;
        const D3D12_BOX box = { x0, y0, 0, x0 + PATCH, y0 + PATCH, 1 };
        LD_CL(CopyTextureRegion, &dst, 0, 0, 0, &src, &box);
    }
    b.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_SOURCE;
    b.Transition.StateAfter = D3D12_RESOURCE_STATE_RENDER_TARGET;
    LD_CL(ResourceBarrier, 1, &b);
    pending = 1; fp16_pending = fp16;
}

